# Very explicit list concatenation

def expand_row(row):
    expanded = [row[0], row[0], row[1], row[1], row[2], row[2]]
    return expanded[:5]

test_input = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]

output = []
for i, row in enumerate(test_input):
    out_row = expand_row(row)
    if i in [0, 2]:
        output.append(out_row)
        output.append(out_row)
    else:
        output.append(out_row)

print("Output:")
for row in output:
    print(row)
